if (typeof globalThis === 'undefined') {
  const isIos =
    !navigator.userAgentData && navigator.userAgent.indexOf('iPhone OS') >= 0;
  const oldBrowserTipDialog = document.createElement('div');
  oldBrowserTipDialog.classList.add('cp-browser-overlay');
  if (isIos) {
    oldBrowserTipDialog.innerHTML =
      '<div class="cp-browser-dialog">' +
      '<div class="cp-browser-title">请升级系统</div>' +
      '<div class="cp-browser-content">' +
      '<p>您的系统版本过低，网站已不再兼容。这意味着在升级系统之前，您无法正常使用网站。</p>' +
      '<p>进入手机或平板的设置，你应该会直接看到“软件更新”的选项，升级之后就可以访问网站了。</p>' +
      '<p>如果你还是没搞清楚怎么升级，可以请教身边懂手机的朋友。</p>' +
      '</div>' +
      '</div>';
  } else {
    oldBrowserTipDialog.innerHTML =
      '<div class="cp-browser-dialog">' +
      '<div class="cp-browser-title">请升级浏览器</div>' +
      '<div class="cp-browser-content">' +
      '<p>您的浏览器版本过低，网站已不再兼容。这意味着在升级浏览器之前，您无法正常使用网站。</p>' +
      '<p>我们推荐你从以下浏览器中选择一款（优先推荐使用Google Chrome）</p>' +
      '<ul class="cp-browser-download">' +
      '<li>' +
      '<a class="cp-browser-download-links" href="https://google.cn/chrome/" target="_blank">' +
      '<picture class="cp-browser-download-icon">' +
      '<source srcset="/browser-logos/Browser_Google_Chrome.webp" type="image/webp" />' +
      '<img src="/browser-logos/Browser_Google_Chrome.png" width="128" height="128" />' +
      '</picture>' +
      '<div class="cp-browser-download-name">Google Chrome</div>' +
      '<div class="cp-browser-download-description">谷歌出品，兼容性最好</div>' +
      '</a>' +
      '</li>' +
      '<li>' +
      '<a class="cp-browser-download-links" href="https://www.firefox.com/zh-CN/" target="_blank">' +
      '<picture class="cp-browser-download-icon">' +
      '<source srcset="/browser-logos/Browser_Firefox.webp" type="image/webp" />' +
      '<img src="/browser-logos/Browser_Firefox.png" width="128" height="133" />' +
      '</picture>' +
      '<div class="cp-browser-download-name">Mozilla Firefox</div>' +
      '<div class="cp-browser-download-description">会保护隐私的浏览器</div>' +
      '</a>' +
      '</li>' +
      '<li>' +
      '<a class="cp-browser-download-links" href="https://www.microsoft.com/zh-cn/edge/download" target="_blank">' +
      '<picture class="cp-browser-download-icon">' +
      '<source srcset="/browser-logos/Browser_Microsoft_Edge.webp" type="image/webp" />' +
      '<img src="/browser-logos/Browser_Microsoft_Edge.png" width="128" height="128" />' +
      '</picture>' +
      '<div class="cp-browser-download-name">Microsoft Edge</div>' +
      '<div class="cp-browser-download-description">数据同步免翻墙</div>' +
      '</a>' +
      '</li>' +
      '</ul>' +
      '</div>' +
      '</div>';
  }
  document.body.appendChild(oldBrowserTipDialog);
  document.body.style.position = 'fixed';
  document.body.style.top = '0';
}
